final_submission.code:
if (points.empty()) {
    return BoundingBox2(Point2d(0, 0), Point2d(0, 0));
}

// Compute convex hull first
std::vector<Point2d> convexHull = points;
std::sort(convexHull.begin(), convexHull.end());
std::vector<Point2d> hull;
for (size_t i = 0; i < convexHull.size(); ++i) {
    while (hull.size() >= 2 && cross(hull[hull.size()-2], hull.back(), convexHull[i]) <= 0)
        hull.pop_back();
    hull.push_back(convexHull[i]);
}
size_t lower_hull_size = hull.size();
for (size_t i = convexHull.size()-1; i > 0; --i) {
    while (hull.size() > lower_hull_size && cross(hull[hull.size()-2], hull.back(), convexHull[i-1]) <= 0)
        hull.pop_back();
    hull.push_back(convexHull[i-1]);
}
hull.pop_back(); // Remove duplicate point

// Find minimum area bounding rectangle
double min_area = std::numeric_limits<double>::max();
BoundingBox2 result(Point2d(0, 0), Point2d(0, 0));

for (size_t i = 0; i < hull.size(); ++i) {
    Point2d p1 = hull[i];
    Point2d p2 = hull[(i+1) % hull.size()];
    Point2d edge = p2 - p1;
    double edge_length = edge.length();
    if (edge_length < 1e-10) continue;

    // Normalize edge vector
    edge = edge / edge_length;

    // Find projections of all points onto the edge
    std::vector<double> projections;
    for (const Point2d& p : hull) {
        double proj = (p - p1) * edge;
        projections.push_back(proj);
    }

    // Find min and max projections
    double min_proj = *std::min_element(projections.begin(), projections.end());
    double max_proj = *std::max_element(projections.begin(), projections.end());

    // Find projections perpendicular to the edge
    Point2d perpendicular(-edge.y(), edge.x());
    std::vector<double> perp_projections;
    for (const Point2d& p : hull) {
        double proj = (p - p1) * perpendicular;
        perp_projections.push_back(proj);
    }

    // Find min and max perpendicular projections
    double min_perp = *std::min_element(perp_projections.begin(), perp_projections.end());
    double max_perp = *std::max_element(perp_projections.begin(), perp_projections.end());

    // Calculate area
    double width = max_proj - min_proj;
    double height = max_perp - min_perp;
    double area = width * height;

    if (area < min_area) {
        min_area = area;
        Point2d min_corner = p1 + min_proj * edge + min_perp * perpendicular;
        Point2d max_corner = p1 + max_proj * edge + max_perp * perpendicular;
        result = BoundingBox2(min_corner, max_corner);
    }
}

return result;

